      C: "#include <stdio.h>\nint binarySearch(int arr[], int size, int target) {\n    int left = 0;\n    int right = size - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (arr[mid] == target) {\n            return mid;\n        } else if (arr[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return -1;\n}\nint main() {\n    int arr[] = {1, 3, 5, 7, 9};\n    int size = sizeof(arr) / sizeof(arr[0]);\n    printf(\"%d\\n\", binarySearch(arr, size, 5));\n    return 0;\n}",
