      JavaScript: "function mergeSorted(lst1, lst2) {\n    const result = [];\n    let i = 0, j = 0;\n    while (i < lst1.length && j < lst2.length) {\n        if (lst1[i] <= lst2[j]) {\n            result.push(lst1[i]);\n            i++;\n        } else {\n            result.push(lst2[j]);\n            j++;\n        }\n    }\n    result.push(...lst1.slice(i));\n    result.push(...lst2.slice(j));\n    return result;\n}\n\nconsole.log(mergeSorted([1, 3, 5], [2, 4, 6]));",
