    title: "Valid Parentheses",
    description: "Check if a string has valid parentheses.",
    difficulty: "Medium",
    language: "Python",
    category: "Strings",
    starterCode:
      "def is_valid_parentheses(s):\n    # Your code here\n    pass\n\nprint(is_valid_parentheses('()[]{}'))",
    solutions: {
      Python: "def is_valid_parentheses(s):\n    stack = []\n    pairs = {'(': ')', '[': ']', '{': '}'}\n    for char in s:\n        if char in pairs:\n            stack.append(char)\n        else:\n            if not stack or pairs[stack.pop()] != char:\n                return False\n    return len(stack) == 0\n\nprint(is_valid_parentheses('()[]{}'))",
      JavaScript: "function isValidParentheses(s) {\n    const stack = [];\n    const pairs = { '(': ')', '[': ']', '{': '}' };\n    for (let char of s) {\n        if (pairs[char]) {\n            stack.push(char);\n        } else {\n            if (!stack || pairs[stack.pop()] !== char) {\n                return false;\n            }\n        }\n    }\n    return stack.length === 0;\n}\n\nconsole.log(isValidParentheses('()[]{}'));",
      Java: "import java.util.Stack;\npublic class IsValidParentheses {\n    public static boolean isValidParentheses(String s) {\n        Stack<Character> stack = new Stack<>();\n        Map<Character, Character> pairs = Map.of('(', ')', '[', ']', '{', '}');\n        for (char c : s.toCharArray()) {\n            if (pairs.containsKey(c)) {\n                stack.push(c);\n            } else {\n                if (stack.isEmpty() || pairs.get(stack.pop()) != c) {\n                    return false;\n                }\n            }\n        }\n        return stack.isEmpty();\n    }\n    public static void main(String[] args) {\n        System.out.println(isValidParentheses('()[]{}')));\n    }\n}",
      "C++": "#include <iostream>\n#include <stack>\n#include <unordered_map>\nusing namespace std;\nbool isValidParentheses(string s) {\n    stack<char> stack;\n    unordered_map<char, char> pairs = {{'(', ')'}, {'[', ']'}, {'{', '}'} };\n    for (char c : s) {\n        if (pairs.find(c) != pairs.end()) {\n            stack.push(c);\n        } else {\n            if (stack.empty() || pairs[stack.top()] != c) {\n                return false;\n            }\n            stack.pop();\n        }\n    }\n    return stack.empty();\n}\nint main() {\n    cout << isValidParentheses(\"()[]{}\") << endl;\n    return 0;\n}",
      C: "#include <stdio.h>\n#include <stdlib.h>\n#include <stdbool.h>\n#include <string.h>\nbool isValidParentheses(char* s) {\n    char stack[100];\n    int top = -1;\n    char pairs[128];\n    pairs['('] = ')';\n    pairs['['] = ']';\n    pairs['{'] = '}';\n    for (int i = 0; s[i] != '\\0'; i++) {\n        char c = s[i];\n        if (c == '(' || c == '[' || c == '{') {\n            stack[++top] = c;\n        } else {\n            if (top == -1 || pairs[stack[top]] != c) {\n                return false;\n            }\n            top--;\n        }\n    }\n    return top == -1;\n}\nint main() {\n    printf(\"%d\\n\", isValidParentheses(\"()[]{}\"));\n    return 0;\n}",
      Go: "package main\nimport (\n    \"fmt\"\n)\nfunc isValidParentheses(s string) bool {\n    stack := []rune{}\n    pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}\n    for _, char := range s {\n        if char == '(' || char == '[' || char == '{' {\n            stack = append(stack, char)\n        } else {\n            if len(stack) == 0 || pairs[char] != stack[len(stack)-1] {\n                return false\n            }\n            stack = stack[:len(stack)-1]\n        }\n    }\n    return len(stack) == 0\n}\nfunc main() {\n    fmt.Println(isValidParentheses(\"()[]{}\"))\n}",
      Rust: "fn is_valid_parentheses(s: &str) -> bool {\n    let mut stack = Vec::new();\n    let pairs = vec![(')', '('), (']', '['), ('}', '{')].into_iter().collect::<std::collections::HashMap<_, _>>();\n    for char in s.chars() {\n        if pairs.contains_key(&char) {\n            stack.push(char);\n        } else {\n            if stack.is_empty() || pairs[&char] != stack.pop().unwrap() {\n                return false;\n            }\n        }\n    }\n    stack.is_empty()\n}\nfn main() {\n    println!(\"{}\", is_valid_parentheses(\"()[]{}\"));\n}",
      PHP: "<?php\nfunction isValidParentheses($s) {\n    $stack = [];\n    $pairs = [')' => '(', ']' => '[', '}' => '{'];\n    for ($i = 0; $i < strlen($s); $i++) {\n        $char = $s[$i];\n        if (in_array($char, array_values($pairs))) {\n            array_push($stack, $char);\n        } else {\n            if (empty($stack) || $pairs[end($stack)] !== $char) {\n                return false;\n            }\n            array_pop($stack);\n        }\n    }\n    return empty($stack);\n}\necho isValidParentheses('()[]{}');\n?>",
      Ruby: "def is_valid_parentheses(s)\n    stack = []\n    pairs = { ')' => '(', ']' => '[', '}' => '{' }\n    s.each_char do |char|\n        if pairs.values.include?(char)\n            stack.push(char)\n        else\n            if stack.empty? || pairs[char] != stack.pop\n                return false\n            end\n        end\n    end\n    stack.empty?\nend\n\nputs is_valid_parentheses('()[]{}')",
      TypeScript: "function isValidParentheses(s: string): boolean {\n    const stack: string[] = [];\n    const pairs: { [key: string]: string } = { ')': '(', ']': '[', '}': '{' };\n    for (let char of s) {\n        if (Object.values(pairs).includes(char)) {\n            stack.push(char);\n        } else {\n            if (stack.length === 0 || pairs[char] !== stack.pop()) {\n                return false;\n            }\n        }\n    }\n    return stack.length === 0;\n}\n\nconsole.log(isValidParentheses('()[]{}'));",
    },
