      Java: "import java.util.ArrayList;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\npublic class Intersection {\n    public static List<Integer> intersection(List<Integer> lst1, List<Integer> lst2) {\n        Set<Integer> set1 = new HashSet<>(lst1);\n        Set<Integer> set2 = new HashSet<>(lst2);\n        set1.retainAll(set2);\n        return new ArrayList<>(set1);\n    }\n    public static void main(String[] args) {\n        System.out.println(intersection(Arrays.asList(1, 2, 3), Arrays.asList(2, 3, 4)));\n    }\n}",
      "C++": "#include <iostream>\n#include <vector>\n#include <unordered_set>\nusing namespace std;\nvector<int> intersection(vector<int> lst1, vector<int> lst2) {\n    unordered_set<int> set1(lst1.begin(), lst1.end());\n    unordered_set<int> set2(lst2.begin(), lst2.end());\n    vector<int> result;\n    for (int num : set1) {\n        if (set2.find(num) != set2.end()) {\n            result.push_back(num);\n        }\n    }\n    return result;\n}\nint main() {\n    vector<int> result = intersection({1, 2, 3}, {2, 3, 4});\n    for (int num : result) cout << num << \" \";\n    cout << endl;\n    return 0;\n}",
      C: "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nint compare(const void* a, const void* b) {\n    return (*(int*)a - *(int*)b);\n}\nint* intersection(int lst1[], int size1, int lst2[], int size2, int* newSize) {\n    qsort(lst1, size1, sizeof(int), compare);\n    qsort(lst2, size2, sizeof(int), compare);\n    int* result = (int*)malloc(size1 * sizeof(int));\n    int i = 0, j = 0, k = 0;\n    while (i < size1 && j < size2) {\n        if (lst1[i] == lst2[j]) {\n            result[k++] = lst1[i];\n            i++;\n            j++;\n        } else if (lst1[i] < lst2[j]) {\n            i++;\n        } else {\n            j++;\n        }\n    }\n    *newSize = k;\n    return result;\n}\nint main() {\n    int lst1[] = {1, 2, 3};\n    int lst2[] = {2, 3, 4};\n    int size1 = sizeof(lst1) / sizeof(lst1[0]);\n    int size2 = sizeof(lst2) / sizeof(lst2[0]);\n    int newSize;\n    int* result = intersection(lst1, size1, lst2, size2, &newSize);\n    for (int i = 0; i < newSize; i++) printf(\"%d \", result[i]);\n    printf(\"\\n\");\n    free(result);\n    return 0;\n}",
      Go: "package main\nimport (\n    \"fmt\"\n)\nfunc intersection(lst1 []int, lst2 []int) []int {\n    set1 := make(map[int]bool)\n    set2 := make(map[int]bool)\n    for _, num := range lst1 {\n        set1[num] = true\n    }\n    for _, num := range lst2 {\n        set2[num] = true\n    }\n    var result []int\n    for num := range set1 {\n        if set2[num] {\n            result = append(result, num)\n        }\n    }\n    return result\n}\nfunc main() {\n    fmt.Println(intersection([]int{1, 2, 3}, []int{2, 3, 4}))\n}",
