      PHP: "<?php\nfunction intersection($lst1, $lst2) {\n    $set1 = array_flip($lst1);\n    $set2 = array_flip($lst2);\n    $result = array_intersect_key($set1, $set2);\n    return array_keys($result);\n}\nprint_r(intersection([1, 2, 3], [2, 3, 4]));\n?>",
